# The type characters the originals register their functions with.
REGISTERED_TYPES = {"%": "Int32", "#": "Float32", "$": "String"}
REGISTERED_PARAMETER = re.compile(r'([%#$])(\w+)(?:=("[^"]*"|[^%#$]*))?')
SIGNATURE = re.compile(r"^(\w+)(?::(\w+))?(?:\((.*)\))?$")
PARAMETER = re.compile(r"^(?:(Out|InOut) )?(\w+):(\w+)(?: = (.*))?$")


def from_registered(signature):
    """The signature of the list for one the originals register, such as %LoadImage$bmpfile%frame=0."""
    ret = REGISTERED_TYPES.get(signature[:1])
    body = signature[1:] if ret else signature
    name = re.match(r"\w+", body).group(0)
    rest = body[len(name):]
    parameters = REGISTERED_PARAMETER.findall(rest)
    if REGISTERED_PARAMETER.sub("", rest):
        raise ValueError("can not read the registered signature %r" % signature)
    return format_signature(name, ret, [("", n, REGISTERED_TYPES[t], d) for t, n, d in parameters])


def format_signature(name, ret, parameters):
    """Writes a signature of the list. parameters are (mode, name, type, default): mode is "", "Out" or "InOut", the
    default "" for a parameter that has to be given."""
    text = ", ".join("%s%s:%s%s" % (mode + " " if mode else "", n, t, " = " + d if d else "") for mode, n, t, d in parameters)
    return "%s%s(%s)" % (name, ":" + ret if ret else "", text)


def parse_signature(signature):
    """(name, result, parameters) of a signature of the list; result is None for a command without one, and the parameters
    are (mode, name, type, default) as format_signature takes them. A bare name is a command without parameters."""
    m = SIGNATURE.match(signature)
    if not m:
        raise ValueError("can not read the signature %r" % signature)
    parameters = []
    for part in split_parameters(m.group(3) or ""):
        p = PARAMETER.match(part)
        if not p:
            raise ValueError("can not read the parameter %r of %r" % (part, signature))
        parameters.append((p.group(1) or "", p.group(2), p.group(3), p.group(4) or ""))
    return m.group(1), m.group(2), parameters


def split_parameters(text):
    """The parameters of a signature, split at the commas that are not inside a string default."""
    parts, current, quoted = [], "", False
    for c in text:
        if c == '"':
            quoted = not quoted
        if c == "," and not quoted:
            parts.append(current.strip())
            current = ""
        else:
            current += c
    if current.strip():
        parts.append(current.strip())
    return parts


# The signature is a C string literal: an escaped quote (the "" default of a string parameter) belongs to it.
SYMBOL = re.compile(r'(?:rtSym|sym)\(\s*"((?:[^"\\]|\\.)+)"')
NAME = re.compile(r"^[%#$]?([A-Za-z_][A-Za-z0-9_]*)")


def originals():
    found = {}
    for source in ("blitz3d", "blitzplus_msvc2017"):
        base = os.path.join(ROOT, "third_party", source)
        for directory, _, files in os.walk(base):
            for name in sorted(files):
                if not name.endswith(".cpp") or name not in MODULES:
                    continue
                text = open(os.path.join(directory, name), errors="replace").read()
                # What the original has commented out is not registered, and so does not exist for programs.
                text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
                text = re.sub(r"^\s*//.*$", "", text, flags=re.M)
                for match in SYMBOL.finditer(text):
                    n = NAME.match(match.group(1))
                    if not n or n.group(1).startswith("_"):
                        continue
                    found.setdefault(n.group(1).lower(), (MODULES[name], from_registered(re.sub(r"\\(.)", r"\1", match.group(1)))))
    for name, entry in UNREGISTERED.items():
        found.setdefault(name, entry)
    found.update(EXTENDED)
    for name, entry in EXTENSIONS.items():
        found.setdefault(name, entry)
    return found


def implemented():
    text = open(os.path.join(ROOT, "code_compiler", "source", "builtins.inc")).read()
    return {name.lower() for name in re.findall(r'\{\s*"([A-Za-z0-9_]+)"', text)} | BY_COMPILER


def compiler_words():
    """Every word that the compiler sources have in quotes, which is where it handles the functions of BY_COMPILER."""
    words = set()
    directory = os.path.join(ROOT, "code_compiler", "source")
    for name in os.listdir(directory):
        if name.endswith((".cpp", ".hpp")):
            words |= set(re.findall(r'"([a-z0-9_]+)"', open(os.path.join(directory, name), errors="replace").read().lower()))
    return words


def have_originals():
    """Whether the submodules with the original sources are checked out."""
    return all(os.path.exists(os.path.join(ROOT, "third_party", d, ".git")) for d in ("blitz3d", "blitzplus_msvc2017"))


def require_originals():
    if not have_originals():
        raise SystemExit("the list of functions is made from the original sources, which are not checked out: run "
                         "git submodule update --init --depth 1 third_party/blitz3d third_party/blitzplus_msvc2017")


def read_list():
    """The list of functions as rows of name, module, state and signature."""
    return [list(row) for row in list_text()[1]]


def list_text():
    """The list of functions as 'list' writes it, made from the originals and the tables above."""
    require_originals()
    done = implemented()
    rows = []
    for name, (module, signature) in sorted(originals().items(), key=lambda item: (item[1][0], item[0])):
        rows.append((name, module, "done" if name in done else "pending", signature))
    text = "# name\tmodule\tstate\tsignature (Name:Result(parameter:Type = default), see tools/suite_functions.py)\n"
    return text + "".join("\t".join(row) + "\n" for row in rows), rows


def command_list(path):
    text, rows = list_text()
    if path is None:
        sys.stdout.write(text)
        return
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as out:
        out.write(text)
    print("%d functions, %d pending" % (len(rows), sum(1 for r in rows if r[2] == "pending")))


def example_arguments(signature):
    """Arguments for a call of the function, made from its signature."""
    arguments = []
    for mode, name, kind, default in parse_signature(signature)[2]:
        if default:
            continue
        arguments.append('""' if kind == "String" else ("1.0" if kind.startswith("Float") else "1"))
    return ", ".join(arguments)


def command_pending():
    os.makedirs(PENDING, exist_ok=True)
    for name, module, state, signature in read_list():
        path = os.path.join(PENDING, "%s.bb" % name)
        if state != "pending" or os.path.exists(path):
            continue
        returns = parse_signature(signature)[1] is not None
        call = "%s(%s)" % (name, example_arguments(signature)) if returns else "%s %s" % (name, example_arguments(signature))
        with open(path, "w", newline="\n") as out:
            out.write("; AUTOGENERATED COPYRIGHT HEADER START\n")
            out.write("; Copyright (C) 2025 Michael Fabian 'Xaymar' Dirks <info@xaymar.com>\n")
            out.write("; AUTOGENERATED COPYRIGHT HEADER END\n")
            out.write("; %s (%s) is not implemented yet. This fails to compile until it is. Once it is, replace this with a\n" % (name, module))
            out.write("; real test in the module's file and delete this one.\n")
            out.write("; Signature: %s\n" % signature)
            out.write(("Local result = %s\n" % call) if returns else ("%s\n" % call))
    print("pending tests written")


def command_check():
    if not have_originals():
        # ctest takes this as skipped (SKIP_RETURN_CODE), not as passed.
        print("the originals are not in /third_party, so the coverage is not checked")
        return 77
    text = ""
    for directory, _, files in os.walk(SUITE):
        if directory.startswith(PENDING):
            continue
        for name in files:
            if name.endswith(".bb"):
                text += open(os.path.join(directory, name), errors="replace").read().lower() + "\n"
    words = set(re.findall(r"[a-z_][a-z0-9_]*", text))
    problems = 0
    handled = compiler_words()
    for name in sorted(BY_COMPILER):
        if name not in handled:
            print("%s is listed in BY_COMPILER but the compiler does not handle it" % name)
            problems += 1
    for name, module, state, signature in read_list():
        if state == "done":
            if name not in words:
                print("%s (%s) has no test" % (name, module))
                problems += 1
            if os.path.exists(os.path.join(PENDING, "%s.bb" % name)):
                print("%s is implemented, so pending/%s.bb should be deleted" % (name, name))
                problems += 1
        else:
            if not os.path.exists(os.path.join(PENDING, "%s.bb" % name)):
                print("%s is pending and has no placeholder, run 'pending'" % name)
                problems += 1
    print("%d problems" % problems)
    return 1 if problems else 0


if __name__ == "__main__":
    command = sys.argv[1] if len(sys.argv) > 1 else "check"
    if command == "list":
        command_list(sys.argv[2] if len(sys.argv) > 2 else None)
    elif command == "pending":
        command_pending()
    elif command == "check":
        sys.exit(command_check())
    else:
        print(__doc__)
        sys.exit(2)
